/**
 * `morphoVaultV2Abi` — the READ surface of a **Morpho Vault V2** (feature 024, constitution v3.0.0).
 *
 * Hand-written and web-local on purpose. `@sparkpoint/shared/abis` is AUTO-GENERATED by
 * `contracts/script/export-abis.sh` from OUR contracts, and a Vault V2 is **Morpho's** contract — it
 * has no artifact in this repo to export from. The precedent is already here: `useVault.ts` declares
 * `morphoWrapperViewsAbi` and `vaultFactoryProvenanceAbi` inline for the same reason.
 *
 * LEAF MODULE, DELIBERATELY: no imports at all, so a pure `node --experimental-strip-types` test can
 * import it directly. (Reaching for `@/…`, an extensionless sibling value-import, or the shared-abis
 * barrel is what breaks that runner.)
 *
 * ── WHY A SEPARATE ABI AND NOT AN EXTENSION OF `sparkPointVaultAbi` ────────────────────────────────
 * A Vault V2 is NOT a superset of SparkPoint's ERC-4626. It exposes **none** of:
 *
 *   `label()` · `morphoVault()` · `factory()` · `isSparkPointVault()` · `highWaterMark()`
 *   `paused()` · `performanceFeeBps()` · `MAX_PERFORMANCE_FEE_BPS()` · `feeRecipient()`
 *
 * Pointing the launch-vault ABI at one does not throw — `useReadContracts({allowFailure: true})`
 * quietly resolves each missing read to `undefined` — and that silence is the danger, not the revert.
 * An `undefined` `performanceFeeBps` falls through to the policy DEFAULT of 1000, so the UI would
 * display a confident **10% fee that was never read from the vault**. On this vault the real fee is
 * 0. Fabricating a fee figure is exactly what Principle III forbids, so the read path must know
 * which contract it is talking to.
 *
 * ── THREE TRAPS ENCODED HERE ──────────────────────────────────────────────────────────────────────
 *
 * 1. **`performanceFee()` / `managementFee()` are WAD-scaled, not bps.** `1e18 == 100%`. Converting
 *    needs exact integer arithmetic: `wad * 10000` reaches 1e22 for a 25% fee, which overflows
 *    64-bit signed arithmetic — the FR-020 gate hit precisely that and silently wrapped a 25% fee to
 *    −8 bps, passing a 0-bps ceiling. In TS use `bigint`, never `number`.
 *
 * 2. **`decimals()` here is the SHARE decimals (18), not the asset's (6).** A V2 applies a decimals
 *    offset (`virtualShares() == 1e12`). Any consumer scaling an ASSET amount must read `decimals()`
 *    on `asset()` instead. Conflating them is a 1e12 error: 100 USDC renders as ~0.0000000001 and the
 *    position drops out of net worth entirely.
 *
 * 3. **`maxDeposit`/`maxMint`/`maxWithdraw`/`maxRedeem` are `pure returns (0)`** on a V2 and are NOT
 *    enforced inside `deposit`/`withdraw`. They are therefore **deliberately ABSENT from this ABI**,
 *    so no surface can accidentally derive a limit from them. A naive read would tell a holder
 *    "you cannot withdraw", which is both false and the worst possible thing to say (N2).
 *
 * Every entry is `view`/`pure` except the four ERC-4626 mutators, which are here because the
 * confirm/execute path needs their calldata shape. Nothing here signs or holds a key.
 */
export const morphoVaultV2Abi = [
  // ── ERC-4626 / ERC-20 identity ────────────────────────────────────────────────────────────────
  { type: "function", name: "asset", stateMutability: "view", inputs: [], outputs: [{ type: "address" }] },
  { type: "function", name: "name", stateMutability: "view", inputs: [], outputs: [{ type: "string" }] },
  { type: "function", name: "symbol", stateMutability: "view", inputs: [], outputs: [{ type: "string" }] },
  /** SHARE decimals — 18 over a 6-dp asset. See trap 2. */
  { type: "function", name: "decimals", stateMutability: "view", inputs: [], outputs: [{ type: "uint8" }] },
  { type: "function", name: "totalAssets", stateMutability: "view", inputs: [], outputs: [{ type: "uint256" }] },
  { type: "function", name: "totalSupply", stateMutability: "view", inputs: [], outputs: [{ type: "uint256" }] },
  {
    type: "function",
    name: "balanceOf",
    stateMutability: "view",
    inputs: [{ type: "address" }],
    outputs: [{ type: "uint256" }],
  },
  {
    type: "function",
    name: "allowance",
    stateMutability: "view",
    inputs: [{ type: "address" }, { type: "address" }],
    outputs: [{ type: "uint256" }],
  },

  // ── conversions + previews (round in the vault's favour, as ERC-4626 requires) ─────────────────
  {
    type: "function",
    name: "convertToAssets",
    stateMutability: "view",
    inputs: [{ type: "uint256" }],
    outputs: [{ type: "uint256" }],
  },
  {
    type: "function",
    name: "convertToShares",
    stateMutability: "view",
    inputs: [{ type: "uint256" }],
    outputs: [{ type: "uint256" }],
  },
  {
    type: "function",
    name: "previewDeposit",
    stateMutability: "view",
    inputs: [{ type: "uint256" }],
    outputs: [{ type: "uint256" }],
  },
  {
    type: "function",
    name: "previewMint",
    stateMutability: "view",
    inputs: [{ type: "uint256" }],
    outputs: [{ type: "uint256" }],
  },
  {
    type: "function",
    name: "previewWithdraw",
    stateMutability: "view",
    inputs: [{ type: "uint256" }],
    outputs: [{ type: "uint256" }],
  },
  {
    type: "function",
    name: "previewRedeem",
    stateMutability: "view",
    inputs: [{ type: "uint256" }],
    outputs: [{ type: "uint256" }],
  },

  // ── fees. WAD-scaled (1e18 == 100%) — see trap 1. There is NO highWaterMark(): a V2 keeps no such
  //    state, which is exactly why T024's fee basis for this kind is `per_period_gain`. ───────────
  { type: "function", name: "performanceFee", stateMutability: "view", inputs: [], outputs: [{ type: "uint256" }] },
  { type: "function", name: "managementFee", stateMutability: "view", inputs: [], outputs: [{ type: "uint256" }] },
  {
    type: "function",
    name: "performanceFeeRecipient",
    stateMutability: "view",
    inputs: [],
    outputs: [{ type: "address" }],
  },
  {
    type: "function",
    name: "managementFeeRecipient",
    stateMutability: "view",
    inputs: [],
    outputs: [{ type: "address" }],
  },

  // ── governance surface, all read-only here. Surfaced so the Trust Center can PROVE the posture
  //    (owner/curator = the 2-of-3 Safe; the critical gates permanently abdicated) rather than
  //    asserting it in prose. `abdicated(bytes4)` is the N2 evidence. ───────────────────────────────
  { type: "function", name: "owner", stateMutability: "view", inputs: [], outputs: [{ type: "address" }] },
  { type: "function", name: "curator", stateMutability: "view", inputs: [], outputs: [{ type: "address" }] },
  {
    type: "function",
    name: "isSentinel",
    stateMutability: "view",
    inputs: [{ type: "address" }],
    outputs: [{ type: "bool" }],
  },
  {
    type: "function",
    name: "isAllocator",
    stateMutability: "view",
    inputs: [{ type: "address" }],
    outputs: [{ type: "bool" }],
  },
  {
    type: "function",
    name: "abdicated",
    stateMutability: "view",
    inputs: [{ type: "bytes4" }],
    outputs: [{ type: "bool" }],
  },
  {
    type: "function",
    name: "timelock",
    stateMutability: "view",
    inputs: [{ type: "bytes4" }],
    outputs: [{ type: "uint256" }],
  },
  { type: "function", name: "virtualShares", stateMutability: "view", inputs: [], outputs: [{ type: "uint256" }] },
  { type: "function", name: "maxRate", stateMutability: "view", inputs: [], outputs: [{ type: "uint256" }] },
  { type: "function", name: "liquidityAdapter", stateMutability: "view", inputs: [], outputs: [{ type: "address" }] },
  { type: "function", name: "adapterRegistry", stateMutability: "view", inputs: [], outputs: [{ type: "address" }] },

  // ── the four ERC-4626 mutators. Present for CALLDATA SHAPE only — the user signs these from their
  //    own wallet; nothing in this repo holds a key. `redeem`/`withdraw` are the N2 exit and are
  //    never gated by any SparkPoint decision. ─────────────────────────────────────────────────────
  {
    type: "function",
    name: "deposit",
    stateMutability: "nonpayable",
    inputs: [{ type: "uint256" }, { type: "address" }],
    outputs: [{ type: "uint256" }],
  },
  {
    type: "function",
    name: "mint",
    stateMutability: "nonpayable",
    inputs: [{ type: "uint256" }, { type: "address" }],
    outputs: [{ type: "uint256" }],
  },
  {
    type: "function",
    name: "withdraw",
    stateMutability: "nonpayable",
    inputs: [{ type: "uint256" }, { type: "address" }, { type: "address" }],
    outputs: [{ type: "uint256" }],
  },
  {
    type: "function",
    name: "redeem",
    stateMutability: "nonpayable",
    inputs: [{ type: "uint256" }, { type: "address" }, { type: "address" }],
    outputs: [{ type: "uint256" }],
  },
  /**
   * The escape hatch when a Blue market cannot currently pay out: force the vault to pull liquidity
   * back from an adapter so a redeem can settle. Part of the N2 exit surface, penalty currently 0.
   */
  {
    type: "function",
    name: "forceDeallocate",
    stateMutability: "nonpayable",
    inputs: [{ type: "address" }, { type: "bytes" }, { type: "uint256" }, { type: "address" }],
    outputs: [{ type: "uint256" }],
  },
] as const;

/**
 * WAD (1e18 = 100%) → basis points, rounded **UP**, in exact integer arithmetic.
 *
 * Rounded up because every consumer compares this against a CEILING: truncating down would let a fee
 * a hair above the limit (`0.200001e18`) read as exactly 2000 bps and pass a 2000-bps cap. Erring
 * upward can only ever make us refuse or over-disclose, never under-disclose.
 *
 * `bigint` throughout, not `number`: `wad * 10000n` reaches 1e22 for a 25% fee. The shell version of
 * this same conversion in the FR-020 gate wrapped that to **−8 bps** and passed a 0-bps ceiling
 * before it was caught — the identical trap exists in JS if anyone routes it through a float.
 */
export function wadToBpsCeil(wad: bigint): number {
  if (wad <= 0n) return 0;
  return Number((wad * 10_000n + 10n ** 18n - 1n) / 10n ** 18n);
}
